"use client"

import { Button } from "@/components/ui/button"
import { Spinner } from "@/components/ui/spinner"
import { cn } from "@/lib/utils"
import {
  CONFIGURED_ALERTS,
  SEVERITY_ORDER,
  type AlertAnalysis,
  type Detection,
} from "@/lib/mockups/behavioral-alerts-data"
import { ScenarioSettingsIcon } from "@/components/mockups/behavioral-alerts/icons"
import { formatTimeSeconds } from "@/components/mockups/behavioral-alerts/recording-player"
import { Seekable } from "@/components/mockups/behavioral-alerts/seekable"
import {
  SEVERITY_RULE,
  SeverityBadge,
} from "@/components/mockups/behavioral-alerts/severity"

export function AlertDetectionsBody({
  analysis,
  onConfigureAlerts,
  onSeek,
}: {
  analysis: AlertAnalysis
  onConfigureAlerts: () => void
  onSeek: (seconds: number) => void
}) {
  if (analysis.state === "pending") {
    return (
      <p className="flex items-center gap-2 text-sm text-muted-foreground">
        <Spinner className="size-4 shrink-0" />
        Analysing this call. Detections appear here when the post-call task
        finishes.
      </p>
    )
  }

  if (analysis.state === "unavailable") {
    return (
      <p className="text-sm text-muted-foreground">
        The call ended before anything was said, so there was no transcript to
        analyse.
      </p>
    )
  }

  if (analysis.state === "unconfigured") {
    return (
      <>
        <p className="text-sm text-muted-foreground">
          This scenario has no flags configured, so nothing was watched for.
        </p>
        <Button
          className="self-start"
          onClick={onConfigureAlerts}
          size="sm"
          variant="outline"
        >
          <ScenarioSettingsIcon />
          Configure flags
        </Button>
      </>
    )
  }

  if (analysis.detections.length === 0) {
    return (
      <p className="text-sm text-muted-foreground">
        No configured flag was detected on this call.
      </p>
    )
  }

  const detections = [...analysis.detections].sort(
    (a, b) =>
      SEVERITY_ORDER.indexOf(a.severity) - SEVERITY_ORDER.indexOf(b.severity),
  )

  return (
    <div className="flex flex-col gap-2">
      {detections.map((detection) => (
        <DetectionRow
          detection={detection}
          key={detection.id}
          onSeek={onSeek}
        />
      ))}
    </div>
  )
}

export function detectionsSummary(analysis: AlertAnalysis) {
  if (analysis.state === "pending") return "Analysing"
  if (analysis.state === "unavailable") return "No transcript"
  if (analysis.state === "unconfigured") return "None configured"
  if (analysis.detections.length === 0) return "None detected"
  return `${analysis.detections.length} detected`
}

function DetectionRow({
  detection,
  onSeek,
}: {
  detection: Detection
  onSeek: (seconds: number) => void
}) {
  const alert = CONFIGURED_ALERTS.find((item) => item.id === detection.alertId)

  return (
    <Seekable
      className="flex gap-3 rounded-lg bg-card p-3"
      label={`Seek to ${formatTimeSeconds(detection.at)}`}
      onActivate={() => {
        onSeek(detection.at)
      }}
    >
      <span
        aria-hidden
        className={cn(
          "w-0.5 shrink-0 rounded-sm",
          SEVERITY_RULE[detection.severity],
        )}
      />

      <div className="flex min-w-0 flex-1 flex-col gap-2">
        <div className="flex items-start justify-between gap-2">
          <span className="text-sm font-medium text-foreground">
            {alert?.name ?? detection.alertId}
          </span>
          <SeverityBadge severity={detection.severity} />
        </div>

        <blockquote className="rounded-lg bg-muted p-2">
          <p className="text-sm text-foreground" dir="auto">
            &ldquo;{detection.evidence}&rdquo;
          </p>
          <span className="text-xs text-muted-foreground tabular-nums">
            {formatTimeSeconds(detection.at)}
          </span>
        </blockquote>

        <p className="text-sm text-muted-foreground">{detection.explanation}</p>
      </div>
    </Seekable>
  )
}

"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { Field, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Switch } from "@/components/ui/switch"
import { Textarea } from "@/components/ui/textarea"
import {
  PRIORITY_LABELS,
  PRIORITY_ORDER,
  type AlertPriority,
  type ConfiguredAlert,
} from "@/lib/mockups/behavioral-alerts-data"

const DESCRIPTION_LIMIT = 500

export function AlertFormDialog({
  alert,
  onOpenChange,
  onSave,
  open,
}: {
  alert: ConfiguredAlert | null
  onOpenChange: (open: boolean) => void
  onSave: (alert: ConfiguredAlert) => void
  open: boolean
}) {
  // Seeded once: the parent remounts this on every open (see `key` at the call
  // site).
  const [name, setName] = React.useState(alert?.name ?? "")
  const [description, setDescription] = React.useState(alert?.description ?? "")
  const [priority, setPriority] = React.useState<AlertPriority>(
    alert?.priority ?? "medium",
  )
  const [enabled, setEnabled] = React.useState(alert?.enabled ?? true)

  const complete = name.trim().length > 0 && description.trim().length > 0

  return (
    <Dialog onOpenChange={onOpenChange} open={open}>
      <DialogContent className="sm:max-w-lg">
        <DialogHeader>
          <DialogTitle>{alert ? "Edit flag" : "Add flag"}</DialogTitle>
        </DialogHeader>

        <Field>
          <FieldLabel htmlFor="alert-name">Name</FieldLabel>
          <Input
            id="alert-name"
            onChange={(event) => {
              setName(event.target.value)
            }}
            placeholder="Escalation request"
            value={name}
          />
        </Field>

        <Field>
          <FieldLabel htmlFor="alert-description">Description</FieldLabel>
          <Textarea
            id="alert-description"
            maxLength={DESCRIPTION_LIMIT}
            onChange={(event) => {
              setDescription(event.target.value)
            }}
            placeholder="The caller asks to speak to a manager, a supervisor, or a human agent."
            rows={4}
            value={description}
          />
          <span className="text-xs text-muted-foreground tabular-nums">
            {description.length} / {DESCRIPTION_LIMIT}
          </span>
        </Field>

        <Field>
          <FieldLabel htmlFor="alert-priority">Priority</FieldLabel>
          <Select
            onValueChange={(value) => {
              setPriority(value as AlertPriority)
            }}
            value={priority}
          >
            <SelectTrigger id="alert-priority">
              <SelectValue />
            </SelectTrigger>
            <SelectContent position="popper">
              {PRIORITY_ORDER.map((level) => (
                <SelectItem key={level} value={level}>
                  {PRIORITY_LABELS[level]}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </Field>

        <Field orientation="horizontal">
          <FieldLabel htmlFor="alert-enabled">Enabled</FieldLabel>
          <Switch
            checked={enabled}
            id="alert-enabled"
            onCheckedChange={setEnabled}
          />
        </Field>

        <DialogFooter>
          <DialogClose asChild>
            <Button variant="ghost">Cancel</Button>
          </DialogClose>
          <Button
            disabled={!complete}
            onClick={() => {
              onSave({
                id: alert?.id ?? `alert-${name.trim().toLowerCase()}`,
                name: name.trim(),
                description: description.trim(),
                priority,
                enabled,
              })
            }}
          >
            {alert ? "Save changes" : "Add flag"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

"use client"

import * as React from "react"
import type { PanelImperativeHandle } from "react-resizable-panels"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
  ResizableHandle,
  ResizablePanel,
  ResizablePanelGroup,
} from "@/components/ui/resizable"
import { Separator } from "@/components/ui/separator"
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetTitle,
} from "@/components/ui/sheet"
import {
  CONFIGURED_ALERTS,
  OWNER,
  type CallRow,
} from "@/lib/mockups/behavioral-alerts-data"
import {
  CallCompletedIcon,
  CopyCallLinkIcon,
  CopyIdIcon,
  InboundIcon,
  LanguageIcon,
  OrganizationIcon,
  OutboundIcon,
  OwnerIcon,
  ShowPanelIcon,
  VoicemailIcon,
} from "@/components/mockups/behavioral-alerts/icons"
import { SectionRegister } from "@/components/mockups/behavioral-alerts/section-register"
import { SEVERITY_RULE } from "@/components/mockups/behavioral-alerts/severity"
import {
  TranscriptPanel,
  type Evidence,
} from "@/components/mockups/behavioral-alerts/transcript-panel"

export function CallDrawer({
  call,
  onConfigureAlerts,
  onOpenChange,
  open,
}: {
  call: CallRow | null
  onConfigureAlerts: () => void
  onOpenChange: (open: boolean) => void
  open: boolean
}) {
  if (!call) return null

  return (
    <Sheet onOpenChange={onOpenChange} open={open}>
      <DrawerBody
        call={call}
        key={call.id}
        onConfigureAlerts={onConfigureAlerts}
      />
    </Sheet>
  )
}

function DrawerBody({
  call,
  onConfigureAlerts,
}: {
  call: CallRow
  onConfigureAlerts: () => void
}) {
  const [at, setAt] = React.useState(0)
  const content = React.useRef<HTMLDivElement>(null)

  const transcript = React.useRef<PanelImperativeHandle>(null)
  const panel = React.useRef<PanelImperativeHandle>(null)
  const [hidden, setHidden] = React.useState<"none" | "panel" | "transcript">(
    "none",
  )

  const detections = call.analysis.detections

  const markers = detections.map((detection) => ({
    id: detection.id,
    label: alertName(detection.alertId),
    at: detection.at,
    tone: SEVERITY_RULE[detection.severity],
  }))

  const evidence = new Map<number, Evidence>(
    detections.map((detection) => [
      detection.at,
      { name: alertName(detection.alertId), severity: detection.severity },
    ]),
  )

  return (
    <SheetContent
      className="flex w-full flex-col sm:max-w-6xl! lg:overflow-hidden"
      // The resize handle stops pointerdown natively, so the dialog reads a
      // press on it as outside. Ignore presses that land inside the panel.
      onPointerDownOutside={(event) => {
        const target = event.detail.originalEvent.target
        if (target instanceof Node && content.current?.contains(target)) {
          event.preventDefault()
        }
      }}
      ref={content}
      // Off because it overlapped the Call ID button; Escape and the overlay
      // still close.
      showCloseButton={false}
    >
      <SheetTitle className="sr-only">Call details</SheetTitle>
      <SheetDescription className="sr-only">
        {call.scenario}, {call.phoneNumber}, {call.startedAt}
      </SheetDescription>

      <div className="flex min-h-0 flex-1 flex-col">
        <CallHeader
          actions={
            hidden === "none" ? null : (
              <Button
                onClick={() => {
                  ;(hidden === "transcript"
                    ? transcript
                    : panel
                  ).current?.expand()
                }}
                size="sm"
                variant="outline"
              >
                <ShowPanelIcon />
                {hidden === "transcript" ? "Show transcript" : "Show panel"}
              </Button>
            )
          }
          call={call}
        />

        {/* Sizes are strings on purpose: react-resizable-panels reads a number
           as pixels and a string as a percentage. */}
        <ResizablePanelGroup
          className="min-h-0 flex-1 p-4"
          orientation="horizontal"
        >
          <ResizablePanel
            collapsible
            defaultSize="62%"
            id="transcript"
            minSize="35%"
            onResize={(size) => {
              setHidden((current) =>
                size.asPercentage === 0
                  ? "transcript"
                  : current === "transcript"
                    ? "none"
                    : current,
              )
            }}
            panelRef={transcript}
          >
            <TranscriptPanel
              at={at}
              call={call}
              evidence={evidence}
              markers={markers}
              onSeek={setAt}
            />
          </ResizablePanel>

          <ResizableHandle className="mx-4" withHandle />

          <ResizablePanel
            collapsible
            defaultSize="38%"
            id="panel"
            minSize="22%"
            onResize={(size) => {
              setHidden((current) =>
                size.asPercentage === 0
                  ? "panel"
                  : current === "panel"
                    ? "none"
                    : current,
              )
            }}
            panelRef={panel}
          >
            <SectionRegister
              call={call}
              onConfigureAlerts={onConfigureAlerts}
              onSeek={setAt}
            />
          </ResizablePanel>
        </ResizablePanelGroup>
      </div>
    </SheetContent>
  )
}

function alertName(alertId: string) {
  return CONFIGURED_ALERTS.find((item) => item.id === alertId)?.name ?? alertId
}

function CallHeader({
  actions,
  call,
}: {
  actions?: React.ReactNode
  call: CallRow
}) {
  return (
    <div className="flex shrink-0 flex-col gap-2 border-b p-4">
      <div className="flex items-start justify-between gap-4">
        <div className="flex min-w-0 flex-col gap-1">
          <div className="flex items-center gap-2">
            <h2 className="truncate text-xl font-semibold text-foreground">
              {call.scenario}
            </h2>
            {call.status === "completed" ? (
              <Badge className="bg-success-tint text-success-tint-foreground">
                <CallCompletedIcon />
                completed
              </Badge>
            ) : (
              <Badge className="bg-muted text-muted-foreground">
                <VoicemailIcon />
                voicemail
              </Badge>
            )}
          </div>

          <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-muted-foreground">
            <span className="flex items-center gap-1 font-medium text-foreground">
              {call.direction === "inbound" ? (
                <InboundIcon className="size-3.5" />
              ) : (
                <OutboundIcon className="size-3.5" />
              )}
              {call.phoneNumber}
            </span>
            <Separator className="h-3" orientation="vertical" />
            <span className="flex items-center gap-1">
              <OrganizationIcon className="size-3.5" />
              {OWNER.organization}
            </span>
            <span className="flex items-center gap-1">
              <OwnerIcon className="size-3.5" />
              {OWNER.email}
            </span>
            <span className="flex items-center gap-1">
              <LanguageIcon className="size-3.5" />
              {call.language}
            </span>
            <Separator className="h-3" orientation="vertical" />
            <span>{call.startedAt}</span>
            <span className="tabular-nums">
              {Math.floor(call.duration / 60)}m {call.duration % 60}s
            </span>
          </div>
        </div>

        <div className="flex shrink-0 items-center gap-1">
          <Button size="sm" variant="ghost">
            <CopyCallLinkIcon />
            Link
          </Button>
          <Button size="sm" variant="ghost">
            <CopyIdIcon />
            Call ID
          </Button>
          {actions}
        </div>
      </div>
    </div>
  )
}

