  PRIORITY_LABELS,
  SENTIMENT_LABELS,
  SEVERITY_LABELS,
  type AlertPriority,
  type AlertSeverity,
  type Sentiment,
} from "@/lib/mockups/behavioral-alerts-data"

const SEVERITY_TONE: Record<AlertSeverity, string> = {
